exercises.starter_code:
using System.Collections.Generic;

var ages = new Dictionary<string, int>();
// Alice 25, Bob 30; Go-style map[...]

exercises.solution:
using System.Linq;
using System.Collections.Generic;

var ages = new SortedDictionary<string, int> { ["Alice"] = 25, ["Bob"] = 30 };
var parts = ages.Select(kv => $"{kv.Key}:{kv.Value}");
Console.WriteLine("map[" + string.Join(" ", parts) + "]");

