exercises.starter_code:
using System.Collections.Generic;

var names = new SortedDictionary<string, string>();
// "1"->"One", "2"->"Two"

exercises.solution:
using System.Linq;
using System.Collections.Generic;

var names = new SortedDictionary<string, string> { ["1"] = "One", ["2"] = "Two" };
var parts = names.Select(kv => $"{kv.Key}:{kv.Value}");
Console.Write("map[" + string.Join(" ", parts) + "]");

